-- One paste for the Supabase SQL editor. Generated by tools/supabase/build_apply.py from these migrations, in
-- this order; don't edit by hand. If any statement fails, the whole transaction rolls back and nothing changes.
-- The dashboard may warn about `drop ... if exists` guards and RLS: both are expected (choose Run and enable RLS).
--   20261105120000_lucento_shared.sql
--   20261105120100_lucento_shared_privileges.sql
--   20261106090000_multicurrency.sql
--   20261107090000_entitlements.sql
--   20261108090000_play_purchases.sql

begin;

-- ====================================================================================================
-- 20261105120000_lucento_shared.sql
-- ====================================================================================================
-- Lucento Shared (docs/shared/ARCHITECTURE_PROPOSAL.md): an Owner's financial environment shared with Partners.
--
-- The Shared Space id IS the Owner's auth.users id — the user_id every synced row already carries — so no financial
-- row is rewritten and solo accounts see no change. A Partner is admitted by a membership row. The owner policies on
-- the seven synced tables are widened by exactly that membership:
--   * Partners SELECT every synced table of the space (wallets, categories, transactions, budgets, goals,
--     goal_contributions, recurring), soft-deleted rows included, so sync can pull them.
--   * Partners INSERT and UPDATE transactions of the space. The app's delete is a soft delete (an UPDATE setting
--     deleted_at, see docs/SYNC.md), so this is full add / edit / delete collaboration on transactions.
--   * Everything else — wallets, categories, budgets, goals, contributions, schedules — stays owner-only, and hard
--     DELETE stays owner-only on every table (sync never hard-deletes).
-- Who wrote a transaction is stamped by the database (created_by / updated_by), never taken from the client.
--
-- Membership is one row per Partner (primary key (owner_id, partner_id)), so a later Partner limit above one is a
-- change to lucento_private.max_partners() only — not a schema change. The limit is 1 in this release; it is enforced
-- in accept_space_invite / create_space_invite under advisory locks, the only ways a membership or invitation row can
-- be created (there are no INSERT grants on the three new tables).
--
-- Strictly additive: one private helper schema, three tables, RPCs, two nullable columns on transactions, one on
-- wallets, and new Partner policies beside the existing owner policies. Nothing is dropped, revoked or rewritten, and
-- existing rows keep every value. Privilege hardening is the next migration (20261105120100_lucento_shared_privileges.sql).

-- ------------------------------------------------------------------------------------------------ private helpers
-- Not in an exposed schema: PostgREST can't call these. Only authenticated gets USAGE on the schema (policies run with
-- the querying role's privileges); each helper only ever answers about the caller.

create schema if not exists lucento_private;
grant usage on schema lucento_private to authenticated;

-- The Partner limit per Shared Space: the future entitlement hook (docs/shared/PRODUCT_SPEC.md "max_partners").
-- One in this release, for every space. Nothing else in the schema assumes a single Partner.
create or replace function lucento_private.max_partners(p_owner uuid)
returns integer
language sql
stable
set search_path = ''
as $$
  select 1
$$;

-- Advisory-lock key for every membership change that involves this person (as owner or as partner).
create or replace function lucento_private.space_lock(p_user uuid)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select pg_catalog.hashtextextended('lucento_space:' || p_user::text, 0)
$$;

-- tables first: the helpers below read them

create table if not exists public.shared_spaces (
  owner_id uuid primary key references auth.users (id) on delete cascade,
  owner_label text not null default '' check (char_length(owner_label) <= 60),
  created_at timestamptz not null default now()
);

create table if not exists public.space_members (
  owner_id uuid not null references public.shared_spaces (owner_id) on delete cascade,
  partner_id uuid not null references auth.users (id) on delete cascade,
  partner_label text not null default '' check (char_length(partner_label) <= 60),
  partner_email text not null default '',
  joined_at timestamptz not null default now(),
  primary key (owner_id, partner_id),
  -- A person is a Partner in at most one Shared Space.
  constraint space_members_partner_once unique (partner_id),
  constraint space_members_not_owner check (owner_id <> partner_id)
);

create table if not exists public.space_invites (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.shared_spaces (owner_id) on delete cascade,
  invitee_email text not null check (char_length(invitee_email) between 3 and 254),
  inviter_label text not null default '',
  inviter_email text not null default '',
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'revoked', 'expired')),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  responded_at timestamptz
);
create unique index if not exists space_invites_one_pending_per_email
  on public.space_invites (owner_id, invitee_email) where status = 'pending';
create index if not exists space_invites_owner on public.space_invites (owner_id);
create index if not exists space_invites_invitee_pending on public.space_invites (invitee_email) where status = 'pending';

-- The Shared Spaces the caller belongs to as a Partner (their Owners' ids). Security definer so the policies of
-- space_members can use it without recursing into themselves; it only ever reveals the caller's own memberships.
create or replace function lucento_private.partner_spaces()
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(m.owner_id), '{}'::uuid[])
  from public.space_members m
  where m.partner_id = (select auth.uid())
$$;

-- The caller's email, lowercased, only when it is confirmed (an unconfirmed email never matches an invitation).
create or replace function lucento_private.verified_email()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select lower(u.email) from auth.users u where u.id = (select auth.uid()) and u.email_confirmed_at is not null
$$;

grant execute on function lucento_private.partner_spaces() to authenticated;
grant execute on function lucento_private.verified_email() to authenticated;

-- Defense in depth for "an Owner is never a Partner elsewhere": the RPCs check it under locks; these refuse a row that
-- would break it whatever wrote it.
create or replace function lucento_private.check_space_roles()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_table_name = 'shared_spaces' then
    if exists (select 1 from public.space_members m where m.partner_id = new.owner_id) then
      raise exception 'lucento_space:already_partner';
    end if;
  elsif exists (select 1 from public.shared_spaces s where s.owner_id = new.partner_id) then
    raise exception 'lucento_space:owns_space';
  end if;
  return new;
end;
$$;

create trigger trg_shared_spaces_roles before insert on public.shared_spaces
  for each row execute function lucento_private.check_space_roles();
create trigger trg_space_members_roles before insert on public.space_members
  for each row execute function lucento_private.check_space_roles();

-- ------------------------------------------------------------------------------------------------ access to the new tables
-- Read-only for signed-in users, scoped by RLS (no INSERT/UPDATE/DELETE policy exists, so RLS refuses every direct
-- write); every write goes through the RPCs below.

alter table public.shared_spaces enable row level security;
alter table public.space_members enable row level security;
alter table public.space_invites enable row level security;

grant select on table public.shared_spaces to authenticated;
grant select on table public.space_members to authenticated;
grant select on table public.space_invites to authenticated;

create policy "shared_spaces_select_member" on public.shared_spaces for select to authenticated
  using (owner_id = (select auth.uid()) or owner_id = any ((select lucento_private.partner_spaces())::uuid[]));
create policy "space_members_select_member" on public.space_members for select to authenticated
  using (owner_id = (select auth.uid()) or owner_id = any ((select lucento_private.partner_spaces())::uuid[]));
create policy "space_invites_select_owner_or_invitee" on public.space_invites for select to authenticated
  using (
    owner_id = (select auth.uid())
    or (status = 'pending' and invitee_email = (select lucento_private.verified_email()))
  );

-- ------------------------------------------------------------------------------------------------ financial tables

-- Attribution: who added and who last changed a transaction. Plain uuids, no foreign key: history stays truthful
-- after a Partner's account is deleted. Nullable; rows written before this migration keep null (the Owner's own).
alter table public.transactions
  add column if not exists created_by uuid,
  add column if not exists updated_by uuid;

-- Stamped from the authenticated session on every write; any client value is overwritten. created_by never changes
-- after the insert. Fires after trg_transactions_lww (BEFORE triggers run alphabetically), so an update the conflict
-- rule skips is never stamped.
create or replace function public.lucento_stamp_transaction_actor()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.updated_by := null;
  else
    new.created_by := old.created_by;
    new.updated_by := coalesce(auth.uid(), old.updated_by);
  end if;
  return new;
end;
$$;

create trigger trg_transactions_stamp_actor before insert or update on public.transactions
  for each row execute function public.lucento_stamp_transaction_actor();

-- Wallet classification: an organizational label (Shared, the Owner's personal, a Partner's personal). Never an access
-- rule. Null = never classified (every existing wallet), shown as Shared inside a Shared Space. Wallets stay
-- owner-only to write, so only the Owner sets it. Builds that don't know the column never send it, so an upsert from
-- them leaves it as it is.
alter table public.wallets add column if not exists classification text;
alter table public.wallets add constraint wallets_classification_known
  check (classification is null or classification in ('SHARED', 'OWNER', 'PARTNER'));

-- Partner policies sit beside each table's existing owner policy; permissive policies are OR-ed, so a row is visible
-- (or writable) to its owner as before, and to a Partner of the owner's Shared Space. The owner policies are untouched.
create policy "wallets_select_partner" on public.wallets for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "categories_select_partner" on public.categories for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "transactions_select_partner" on public.transactions for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "budgets_select_partner" on public.budgets for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "goals_select_partner" on public.goals for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "goal_contributions_select_partner" on public.goal_contributions for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "recurring_select_partner" on public.recurring for select to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

-- Transactions: Partners add, edit and (soft-)delete within the space. user_id can never change
-- (lucento_reject_stale_update), so a row can't be moved out of the space either.
create policy "transactions_insert_partner" on public.transactions for insert to authenticated
  with check (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

create policy "transactions_update_partner" on public.transactions for update to authenticated
  using (user_id = any ((select lucento_private.partner_spaces())::uuid[]))
  with check (user_id = any ((select lucento_private.partner_spaces())::uuid[]));

-- ------------------------------------------------------------------------------------------------ RPCs
-- Functions created here start executable by their owner only (this project's default privileges); EXECUTE is granted
-- to authenticated below, never to anon.
-- Each runs as its owner with an empty search_path, takes the caller from auth.uid() (never from an argument), and
-- validates everything inside one transaction. Errors are 'lucento_space:<code>' so the app can say what happened.

-- Everything the Lucento Shared screen needs: the caller's role, the space, its members, the Owner's invitations, and
-- invitations addressed to the caller's verified email.
create or replace function public.get_my_shared_space()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_owner uuid;
  v_role text;
  v_received jsonb;
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_uid and u.email_confirmed_at is not null;
  if exists (select 1 from public.shared_spaces s where s.owner_id = v_uid) then
    v_owner := v_uid;
    v_role := 'OWNER';
  else
    select m.owner_id into v_owner from public.space_members m where m.partner_id = v_uid;
    if v_owner is not null then
      v_role := 'PARTNER';
    end if;
  end if;
  v_received := coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', i.id, 'owner_id', i.owner_id, 'inviter_label', i.inviter_label, 'inviter_email', i.inviter_email,
      'created_at', i.created_at, 'expires_at', i.expires_at
    ) order by i.created_at desc)
    from public.space_invites i
    where v_email is not null and i.invitee_email = v_email and i.status = 'pending' and i.expires_at > now()
      and i.owner_id <> v_uid
  ), '[]'::jsonb);
  if v_owner is null then
    return jsonb_build_object('role', null, 'max_partners', lucento_private.max_partners(v_uid), 'received', v_received);
  end if;
  select jsonb_build_object(
    'role', v_role,
    'owner_id', s.owner_id,
    'owner_label', s.owner_label,
    'owner_email', coalesce((select lower(u.email) from auth.users u where u.id = s.owner_id), ''),
    'created_at', s.created_at,
    'max_partners', lucento_private.max_partners(s.owner_id),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'partner_id', m.partner_id, 'label', m.partner_label, 'email', m.partner_email, 'joined_at', m.joined_at
      ) order by m.joined_at)
      from public.space_members m where m.owner_id = s.owner_id
    ), '[]'::jsonb),
    'invites', case when v_role = 'OWNER' then coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'email', i.invitee_email,
        'status', case when i.status = 'pending' and i.expires_at <= now() then 'expired' else i.status end,
        'created_at', i.created_at, 'expires_at', i.expires_at, 'responded_at', i.responded_at
      ) order by i.created_at desc)
      from (
        select * from public.space_invites x where x.owner_id = s.owner_id
        order by x.created_at desc limit 10
      ) i
    ), '[]'::jsonb) else '[]'::jsonb end,
    'received', v_received
  ) into v_result
  from public.shared_spaces s where s.owner_id = v_owner;
  return v_result;
end;
$$;

-- Creates the caller's Shared Space (or renames it: idempotent). Refused for someone who is a Partner elsewhere.
create or replace function public.create_shared_space(p_owner_label text default '')
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_label text := left(btrim(coalesce(p_owner_label, '')), 60);
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(v_uid));
  if exists (select 1 from public.space_members m where m.partner_id = v_uid) then
    raise exception 'lucento_space:already_partner';
  end if;
  insert into public.shared_spaces (owner_id, owner_label) values (v_uid, v_label)
  on conflict (owner_id) do update
    set owner_label = case when excluded.owner_label <> '' then excluded.owner_label else public.shared_spaces.owner_label end;
end;
$$;

-- The caller's own display name in their Shared Space (as Owner, or as a Partner).
create or replace function public.set_my_space_label(p_label text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_label text := left(btrim(coalesce(p_label, '')), 60);
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  update public.shared_spaces set owner_label = v_label where owner_id = v_uid;
  if found then
    update public.space_invites set inviter_label = v_label where owner_id = v_uid and status = 'pending';
    return;
  end if;
  update public.space_members set partner_label = v_label where partner_id = v_uid;
  if not found then
    raise exception 'lucento_space:no_space';
  end if;
end;
$$;

-- An invitation from the caller's Shared Space to an email address, valid for seven days. Pending invitations count
-- toward the Partner limit, so invitations can never outnumber the free places.
create or replace function public.create_space_invite(p_email text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_own_email text;
  v_label text;
  v_used integer;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  if char_length(v_email) > 254 or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'lucento_space:invalid_email';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(v_uid));
  select s.owner_label into v_label from public.shared_spaces s where s.owner_id = v_uid;
  if not found then
    raise exception 'lucento_space:no_space';
  end if;
  select lower(u.email) into v_own_email from auth.users u where u.id = v_uid;
  if v_email = v_own_email then
    raise exception 'lucento_space:self_invite';
  end if;
  update public.space_invites set status = 'expired', responded_at = now()
    where owner_id = v_uid and status = 'pending' and expires_at <= now();
  if exists (select 1 from public.space_members m where m.owner_id = v_uid and m.partner_email = v_email) then
    raise exception 'lucento_space:already_member';
  end if;
  if exists (select 1 from public.space_invites i where i.owner_id = v_uid and i.status = 'pending' and i.invitee_email = v_email) then
    raise exception 'lucento_space:already_invited';
  end if;
  select (select count(*) from public.space_members m where m.owner_id = v_uid)
       + (select count(*) from public.space_invites i where i.owner_id = v_uid and i.status = 'pending')
    into v_used;
  if v_used >= lucento_private.max_partners(v_uid) then
    raise exception 'lucento_space:space_full';
  end if;
  insert into public.space_invites (owner_id, invitee_email, inviter_label, inviter_email, expires_at)
    values (v_uid, v_email, coalesce(v_label, ''), coalesce(v_own_email, ''), now() + interval '7 days')
    returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.revoke_space_invite(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(v_uid));
  update public.space_invites set status = 'revoked', responded_at = now()
    where id = p_invite_id and owner_id = v_uid and status = 'pending';
  if not found then
    raise exception 'lucento_space:invite_not_found';
  end if;
end;
$$;

-- Joins the Shared Space that sent the invitation. Atomic: the membership row and the accepted invitation are written
-- together or not at all. Both people's locks are taken in a fixed order, so concurrent acceptances (the same
-- invitation twice, two invitations of one space, crossed invitations) are serialised and can't exceed the limit.
create or replace function public.accept_space_invite(p_invite_id uuid, p_partner_label text default '')
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_inv public.space_invites%rowtype;
  v_members integer;
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_uid and u.email_confirmed_at is not null;
  if v_email is null then
    raise exception 'lucento_space:email_unverified';
  end if;
  select * into v_inv from public.space_invites i where i.id = p_invite_id;
  if not found or v_inv.invitee_email <> v_email then
    raise exception 'lucento_space:invite_not_found';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(least(v_inv.owner_id, v_uid)));
  perform pg_advisory_xact_lock(lucento_private.space_lock(greatest(v_inv.owner_id, v_uid)));
  -- Read again under the locks: another acceptance, a revoke or a removal may have committed meanwhile.
  select * into v_inv from public.space_invites i where i.id = p_invite_id for update;
  if not found then
    raise exception 'lucento_space:invite_not_found';
  end if;
  if v_inv.status <> 'pending' then
    raise exception 'lucento_space:invite_%', v_inv.status;
  end if;
  if v_inv.expires_at <= now() then
    raise exception 'lucento_space:invite_expired';
  end if;
  if v_inv.owner_id = v_uid then
    raise exception 'lucento_space:own_space';
  end if;
  if exists (select 1 from public.space_members m where m.partner_id = v_uid) then
    raise exception 'lucento_space:already_partner';
  end if;
  if exists (select 1 from public.shared_spaces s where s.owner_id = v_uid) then
    -- An Owner can't be a Partner elsewhere. A space of the caller's own with nobody in it and nothing pending is
    -- closed so they can join; anything else must be ended by them first.
    if exists (select 1 from public.space_members m where m.owner_id = v_uid)
       or exists (select 1 from public.space_invites i where i.owner_id = v_uid and i.status = 'pending' and i.expires_at > now()) then
      raise exception 'lucento_space:owns_space';
    end if;
    delete from public.shared_spaces where owner_id = v_uid;
  end if;
  select count(*) into v_members from public.space_members m where m.owner_id = v_inv.owner_id;
  if v_members >= lucento_private.max_partners(v_inv.owner_id) then
    raise exception 'lucento_space:space_full';
  end if;
  insert into public.space_members (owner_id, partner_id, partner_label, partner_email)
    values (v_inv.owner_id, v_uid, left(btrim(coalesce(p_partner_label, '')), 60), v_email);
  update public.space_invites set status = 'accepted', responded_at = now() where id = p_invite_id;
  return v_inv.owner_id;
end;
$$;

create or replace function public.decline_space_invite(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_uid and u.email_confirmed_at is not null;
  update public.space_invites set status = 'declined', responded_at = now()
    where id = p_invite_id and v_email is not null and invitee_email = v_email and status = 'pending';
  if not found then
    raise exception 'lucento_space:invite_not_found';
  end if;
end;
$$;

-- The Owner removes a Partner. Their access ends with this statement; what they added stays in the space.
create or replace function public.remove_space_partner(p_partner_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(least(v_uid, p_partner_id)));
  perform pg_advisory_xact_lock(lucento_private.space_lock(greatest(v_uid, p_partner_id)));
  delete from public.space_members where owner_id = v_uid and partner_id = p_partner_id;
  if not found then
    raise exception 'lucento_space:partner_not_found';
  end if;
end;
$$;

-- A Partner leaves. Returns the Owner's id of the space they left.
create or replace function public.leave_shared_space()
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  select m.owner_id into v_owner from public.space_members m where m.partner_id = v_uid;
  if v_owner is null then
    raise exception 'lucento_space:not_partner';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(least(v_owner, v_uid)));
  perform pg_advisory_xact_lock(lucento_private.space_lock(greatest(v_owner, v_uid)));
  delete from public.space_members where partner_id = v_uid;
  if not found then
    raise exception 'lucento_space:not_partner';
  end if;
  return v_owner;
end;
$$;

-- The Owner closes an empty Shared Space (no Partners; pending invitations are withdrawn with it). The ledger is the
-- Owner's own and is untouched.
create or replace function public.close_shared_space()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'lucento_space:not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(lucento_private.space_lock(v_uid));
  if exists (select 1 from public.space_members m where m.owner_id = v_uid) then
    raise exception 'lucento_space:has_partners';
  end if;
  delete from public.shared_spaces where owner_id = v_uid;
  if not found then
    raise exception 'lucento_space:no_space';
  end if;
end;
$$;

grant execute on function public.get_my_shared_space() to authenticated;
grant execute on function public.create_shared_space(text) to authenticated;
grant execute on function public.set_my_space_label(text) to authenticated;
grant execute on function public.create_space_invite(text) to authenticated;
grant execute on function public.revoke_space_invite(uuid) to authenticated;
grant execute on function public.accept_space_invite(uuid, text) to authenticated;
grant execute on function public.decline_space_invite(uuid) to authenticated;
grant execute on function public.remove_space_partner(uuid) to authenticated;
grant execute on function public.leave_shared_space() to authenticated;
grant execute on function public.close_shared_space() to authenticated;

-- ====================================================================================================
-- 20261105120100_lucento_shared_privileges.sql
-- ====================================================================================================
-- Lucento Shared, least privilege for what 20261105120000_lucento_shared.sql created, whatever a project's default
-- privileges are (lucento-test gives new public functions to their owner only, but a project with Supabase's stock
-- defaults would also let anon execute them and hold TRUNCATE on new tables, which row-level security doesn't cover).
-- Same intent as 20261028050634_revoke_extra_table_privileges.sql. Nothing a signed-in user needs is removed:
-- SELECT on the three tables (scoped by RLS) and EXECUTE on the RPCs and on the two helpers the policies call.

revoke all on table public.shared_spaces, public.space_members, public.space_invites from anon, authenticated;
grant select on table public.shared_spaces, public.space_members, public.space_invites to authenticated;

revoke all on schema lucento_private from public, anon;
grant usage on schema lucento_private to authenticated;
revoke all on function
  lucento_private.max_partners(uuid),
  lucento_private.space_lock(uuid),
  lucento_private.partner_spaces(),
  lucento_private.verified_email(),
  lucento_private.check_space_roles()
from public, anon, authenticated;
grant execute on function lucento_private.partner_spaces(), lucento_private.verified_email() to authenticated;

-- Triggers fire without an EXECUTE check, so nobody needs to call this one directly.
revoke all on function public.lucento_stamp_transaction_actor() from public, anon, authenticated;

revoke all on function
  public.get_my_shared_space(),
  public.create_shared_space(text),
  public.set_my_space_label(text),
  public.create_space_invite(text),
  public.revoke_space_invite(uuid),
  public.accept_space_invite(uuid, text),
  public.decline_space_invite(uuid),
  public.remove_space_partner(uuid),
  public.leave_shared_space(),
  public.close_shared_space()
from public, anon;
grant execute on function
  public.get_my_shared_space(),
  public.create_shared_space(text),
  public.set_my_space_label(text),
  public.create_space_invite(text),
  public.revoke_space_invite(uuid),
  public.accept_space_invite(uuid, text),
  public.decline_space_invite(uuid),
  public.remove_space_partner(uuid),
  public.leave_shared_space(),
  public.close_shared_space()
to authenticated;

-- ====================================================================================================
-- 20261106090000_multicurrency.sql
-- ====================================================================================================
-- Multicurrency (docs/CALCULATIONS.md "Exchange rates", docs/MULTICURRENCY.md): wallets in other currencies valued in
-- one main currency by the average-rate method. App database v13.
--
-- Strictly additive. Nothing is dropped, rewritten or revoked from the existing tables, and every existing row keeps
-- every value: the new columns are null (or false) and existing rows follow their wallet's average.
--
--   transactions.base_amount_minor / base_currency / fx_source  — a movement's value in the main currency, the currency
--       it is in (stored with it, so it can never be read in another), and where it came from.
--   wallets.fx_basis_rate  — the rate a foreign wallet's opening balance is valued at, as an exact decimal string.
--   wallets.fx_revalue     — revalue the wallet at each month end.
--   ledger_settings        — the ledger's main currency, set once by its first phone and read by every other phone of the
--       ledger (a reinstall, a second phone, a Partner in a Shared Space). It can't be changed: no update or delete
--       grant or policy exists, and the account's deletion removes it.
--
-- Rollout (docs/SYNC.md): a one-currency ledger's v13 phone sends exactly what v12 sent, so it keeps syncing with a
-- project without this migration. A ledger with a wallet in another currency needs it before such a phone syncs.

-- ------------------------------------------------------------------------------------------------ transactions
alter table public.transactions
  add column if not exists base_amount_minor bigint,
  add column if not exists base_currency text,
  add column if not exists fx_source text;

-- All three or none; the value is in another currency than the row's own; a source this version knows. Live rows only
-- (a soft delete always succeeds) and NOT VALID, like the other financial checks (20261102005820). The "is not null"
-- tests are explicit: a CHECK passes on NULL, so without them a value missing its currency would be accepted.
alter table public.transactions drop constraint if exists transactions_fx_known;
alter table public.transactions add constraint transactions_fx_known check (
  deleted_at is not null
  or (base_amount_minor is null and base_currency is null and fx_source is null)
  or (
    base_amount_minor is not null and base_currency is not null and fx_source is not null
    and base_amount_minor >= 0
    and base_currency ~ '^[A-Z]{3}$'
    and base_currency <> currency_code
    and fx_source in ('MARKET', 'ENTERED', 'LAST_RATE', 'AVERAGE', 'TRANSFER')
  )
) not valid;

-- ------------------------------------------------------------------------------------------------ wallets
alter table public.wallets
  add column if not exists fx_basis_rate text,
  add column if not exists fx_revalue boolean not null default false;

-- A positive decimal written without an exponent ("56.1234", "0.00350877192982"), as the app stores it.
alter table public.wallets drop constraint if exists wallets_fx_basis_known;
alter table public.wallets add constraint wallets_fx_basis_known check (
  deleted_at is not null
  or fx_basis_rate is null
  or (fx_basis_rate ~ '^[0-9]{1,9}(\.[0-9]{1,20})?$' and fx_basis_rate !~ '^0+(\.0+)?$')
) not valid;

-- ------------------------------------------------------------------------------------------------ ledger settings
create table if not exists public.ledger_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  main_currency text not null check (main_currency ~ '^[A-Z]{3}$'),
  created_at timestamptz not null default now()
);

alter table public.ledger_settings enable row level security;

-- One policy per action (no multiple permissive policies): the account reads its own row, and a Partner the row of the
-- Shared Space they belong to (lucento_private.partner_spaces(), 20261105120000_lucento_shared.sql).
drop policy if exists "ledger_settings_select" on public.ledger_settings;
create policy "ledger_settings_select" on public.ledger_settings for select to authenticated
  using (user_id = (select auth.uid()) or user_id = any ((select lucento_private.partner_spaces())::uuid[]));
drop policy if exists "ledger_settings_insert_own" on public.ledger_settings;
create policy "ledger_settings_insert_own" on public.ledger_settings for insert to authenticated
  with check (user_id = (select auth.uid()));

-- Least privilege whatever the project's default privileges are (as 20261105120100_lucento_shared_privileges.sql):
-- read and insert for signed-in users, nothing else, nothing for anon. No UPDATE or DELETE: the main currency is fixed.
revoke all on table public.ledger_settings from anon, authenticated;
grant select, insert on table public.ledger_settings to authenticated;

-- ====================================================================================================
-- 20261107090000_entitlements.sql
-- ====================================================================================================
-- Lucento Pro entitlements (docs/MONETIZATION.md §5.4): what each account's plan unlocks, written by the server, read by the
-- phone. DRAFT — written on feature/lucento-pro-architecture; apply to lucento-test only on the owner's approval, and
-- only together with GRANT rows for the accounts that already share a Shared Space there (max_partners becomes
-- plan-aware below: without a row an Owner can no longer *invite*; existing Partners are untouched — D-16, lenient).
--
-- Strictly additive. Nothing is dropped or rewritten; one existing function (lucento_private.max_partners) changes its
-- answer, which is what it was built for (20261105120000_lucento_shared.sql: "the future entitlement hook").
--
--   entitlements     one row per (account, source, product): the plan rows. Clients read their own; nobody but the
--                    service role writes (the Vercel endpoints verify with the Play Developer API, docs §5.4).
--   purchase_links   one Play purchase ↔ one Lucento account, ever. Service role only; clients never see it.
--   plan_limits      remote configuration (AI allowances, partner capacity), private schema; read by the functions.
--   has_capability   the one question every server-side gate asks: does this account hold LOCAL_PRO / CLOUD / AI_PRO / SHARED now.
--   max_partners     1 with SHARED, else 0 (was: 1 for everyone).
--   consume_ai_request  counts one AI request and answers whether it is within the caller's plan (the proxy's new call;
--                    consume_ai_quota stays for the current proxy until it switches).

-- ------------------------------------------------------------------------------------------------ entitlements
create table if not exists public.entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  source text not null check (source in ('PLAY_SUBSCRIPTION', 'PLAY_LIFETIME', 'PLAY_LIFETIME_SERVICES', 'PLAY_CLOUD_ADDON', 'GRANT')),
  status text not null check (status in ('ACTIVE', 'TRIAL', 'GRACE', 'CANCELLED_ACTIVE', 'ON_HOLD', 'PAUSED', 'PENDING', 'EXPIRED', 'REVOKED')),
  grants text[] not null check (cardinality(grants) > 0 and grants <@ array['LOCAL_PRO', 'CLOUD', 'AI_PRO', 'SHARED']::text[]),
  product_id text check (product_id is null or product_id in ('lucento_pro', 'lucento_pro_lifetime', 'lucento_cloud')),
  base_plan_id text check (base_plan_id is null or char_length(base_plan_id) <= 60),
  purchase_token_hash text check (purchase_token_hash is null or purchase_token_hash ~ '^[0-9a-f]{64}$'),
  starts_at timestamptz not null default now(),
  -- null: never (Lifetime's LOCAL_PRO). A GRANT must have one (the trigger below).
  expires_at timestamptz,
  verified_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- GRANT rows: who and why, for the owner's own bookkeeping; never shown to anyone else.
  note text check (note is null or char_length(note) <= 200),
  constraint entitlements_grant_expires check (source <> 'GRANT' or expires_at is not null),
  constraint entitlements_lifetime_forever check (source <> 'PLAY_LIFETIME' or expires_at is null)
);

create unique index if not exists entitlements_user_source_product
  on public.entitlements (user_id, source, coalesce(product_id, ''));
create index if not exists entitlements_user_idx on public.entitlements (user_id);

alter table public.entitlements enable row level security;
revoke all on table public.entitlements from public, anon, authenticated;
grant select on table public.entitlements to authenticated;

drop policy if exists "entitlements: read own" on public.entitlements;
create policy "entitlements: read own"
  on public.entitlements for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- ------------------------------------------------------------------------------------------------ purchase links
create table if not exists public.purchase_links (
  purchase_token_hash text primary key check (purchase_token_hash ~ '^[0-9a-f]{64}$'),
  order_id text,
  product_id text not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  -- sha256(user id) the app passed to Play at purchase, when the person was signed in; the verifier's proof of intent.
  obfuscated_account_id text,
  linked_at timestamptz not null default now(),
  relinked_count integer not null default 0 check (relinked_count >= 0)
);

alter table public.purchase_links enable row level security;
revoke all on table public.purchase_links from public, anon, authenticated;
-- No policies on purpose: only the service role (which bypasses RLS) reads or writes links.

-- ------------------------------------------------------------------------------------------------ plan limits
create table if not exists lucento_private.plan_limits (
  key text primary key,
  value_int integer not null check (value_int >= 0),
  updated_at timestamptz not null default now()
);
-- Private schema, no client privileges; RLS on top so the dashboard's check and production agree. The functions below
-- are security definer and owned by the table's owner, so RLS never applies to them.
alter table lucento_private.plan_limits enable row level security;
revoke all on table lucento_private.plan_limits from public, anon, authenticated;

insert into lucento_private.plan_limits (key, value_int) values
  ('ai_free_monthly', 10),
  ('ai_pro_daily', 50),
  ('ai_pro_monthly_ceiling', 400),
  ('max_partners_pro', 1)
on conflict (key) do nothing;

create or replace function lucento_private.plan_limit(p_key text, p_default integer)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select l.value_int from lucento_private.plan_limits l where l.key = p_key), p_default)
$$;

-- ------------------------------------------------------------------------------------------------ the one question
-- Does this account hold p_capability right now? Status and dates as the app reads them (Entitlement.covers), without the
-- phone's offline grace: the server is exact.
create or replace function lucento_private.has_capability(p_user uuid, p_capability text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.entitlements e
    where e.user_id = p_user
      and p_capability = any (e.grants)
      and e.status in ('ACTIVE', 'TRIAL', 'GRACE', 'CANCELLED_ACTIVE')
      and (e.expires_at is null or e.expires_at > now())
  )
$$;

revoke all on function lucento_private.plan_limit(text, integer), lucento_private.has_capability(uuid, text)
  from public, anon, authenticated;

-- The Partner limit per Shared Space, now plan-aware (PRODUCT_SPEC §7). Same signature; every caller is unchanged.
create or replace function lucento_private.max_partners(p_owner uuid)
returns integer
language sql
stable
set search_path = ''
as $$
  select case
    when lucento_private.has_capability(p_owner, 'SHARED') then lucento_private.plan_limit('max_partners_pro', 1)
    else 0
  end
$$;

-- ------------------------------------------------------------------------------------------------ AI allowance
-- Counts one request for the caller today (UTC) — the same row as consume_ai_quota — and answers against the plan:
-- Free: ai_free_monthly per calendar month; AI_PRO: ai_pro_daily per day and ai_pro_monthly_ceiling per month.
-- The refused request is counted too, so a client cannot probe for free. The proxy (lucento-website api/ask, api/interpret)
-- calls this with the user's own JWT and returns `remaining` / `limited_by` to the app, which only displays them.
create or replace function public.consume_ai_request()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  v_pro boolean;
  v_today integer;
  v_month integer;
  v_daily integer;
  v_monthly integer;
  v_limited text;
  v_remaining integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  v_pro := lucento_private.has_capability(uid, 'AI_PRO');
  insert into public.ai_usage (user_id, day, requests)
  values (uid, (now() at time zone 'utc')::date, 1)
  on conflict (user_id, day) do update set requests = public.ai_usage.requests + 1
  returning requests into v_today;
  select coalesce(sum(u.requests), 0) into v_month
    from public.ai_usage u
    where u.user_id = uid and u.day >= date_trunc('month', now() at time zone 'utc')::date;
  if v_pro then
    v_daily := lucento_private.plan_limit('ai_pro_daily', 50);
    v_monthly := lucento_private.plan_limit('ai_pro_monthly_ceiling', 400);
    v_limited := case when v_today > v_daily then 'day' when v_month > v_monthly then 'month' else null end;
    v_remaining := greatest(0, least(v_daily - v_today, v_monthly - v_month));
  else
    v_daily := null;
    v_monthly := lucento_private.plan_limit('ai_free_monthly', 10);
    v_limited := case when v_month > v_monthly then 'month' else null end;
    v_remaining := greatest(0, v_monthly - v_month);
  end if;
  return jsonb_build_object(
    'plan', case when v_pro then 'PRO' else 'FREE' end,
    'allowed', v_limited is null,
    'limited_by', v_limited,
    'used_today', v_today,
    'used_month', v_month,
    'daily_limit', v_daily,
    'monthly_limit', v_monthly,
    'remaining', v_remaining
  );
end;
$$;

revoke all on function public.consume_ai_request() from public, anon;
grant execute on function public.consume_ai_request() to authenticated;

-- ------------------------------------------------------------------------------------------------ housekeeping
create or replace function public.lucento_touch_entitlement()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function public.lucento_touch_entitlement() from public, anon, authenticated;

drop trigger if exists entitlements_touch on public.entitlements;
create trigger entitlements_touch before update on public.entitlements
  for each row execute function public.lucento_touch_entitlement();

-- ====================================================================================================
-- 20261108090000_play_purchases.sql
-- ====================================================================================================
-- Lucento Pro, Phase 4 (docs/monetization/SERVER_CONTRACT.md §3–§5): how a Google Play purchase the Vercel endpoints
-- have checked with the Play Developer API becomes this account's entitlement rows. DRAFT — written on
-- feature/lucento-pro-billing; applies after 20261107090000_entitlements.sql (the tables it writes), to lucento-test on the
-- owner's approval and to production only with the gated release.
--
-- Strictly additive: two functions, nothing else. Only the service role may call them (the endpoints hold its key in
-- Vercel env; the app never does), so a client can no more grant itself a plan than before. Each call is one transaction:
-- the linking rule and the row writes can't interleave with another verification of the same purchase.
--
--   apply_play_purchase   verify.ts (for the signed-in account) and rtdn.ts (for the account the purchase is linked to):
--                         applies the §5.4 linking rule, then writes the product's rows from Play's state.
--   revoke_play_purchase  rtdn.ts (voided-purchase notification) and voided.ts (daily Voided Purchases check): a refund or
--                         chargeback ends every row of that purchase. Final: a later verification never revives it.

create or replace function public.apply_play_purchase(
  -- The account verifying (verify.ts). Null: the account this purchase is already linked to (rtdn.ts re-verifying).
  p_user uuid,
  -- sha256 of the purchase token, lower-case hex. The token itself is never stored.
  p_token_hash text,
  p_order_id text,
  p_product_id text,
  -- What Play reports as the order's obfuscatedExternalAccountId: sha256 of the Lucento user id the app passed at purchase.
  p_obfuscated_account_id text,
  -- Play's state in Lucento's vocabulary (the endpoint maps subscriptionsv2 / products states onto these).
  p_status text,
  p_base_plan_id text,
  -- When the purchase was made (Lifetime's included year counts from it, so a reinstall or a re-link can't restart it).
  p_purchased_at timestamptz,
  -- Subscriptions: the end of the current period. Ignored for Lifetime.
  p_expires_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := p_user;
  v_link public.purchase_links%rowtype;
  v_status text := p_status;
  v_starts timestamptz := coalesce(p_purchased_at, now());
  v_services_status text;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'apply_play_purchase: token hash must be 64 lower-case hex characters' using errcode = '22023';
  end if;
  if p_product_id is null or p_product_id not in ('lucento_pro', 'lucento_pro_lifetime', 'lucento_cloud') then
    raise exception 'apply_play_purchase: unknown product %', p_product_id using errcode = '22023';
  end if;
  if p_status is null or p_status not in ('ACTIVE', 'TRIAL', 'GRACE', 'CANCELLED_ACTIVE', 'ON_HOLD', 'PAUSED', 'PENDING', 'EXPIRED', 'REVOKED') then
    raise exception 'apply_play_purchase: unknown status %', p_status using errcode = '22023';
  end if;
  if p_product_id <> 'lucento_pro_lifetime' and v_status not in ('PENDING', 'REVOKED') and p_expires_at is null then
    raise exception 'apply_play_purchase: a subscription needs its period end' using errcode = '22023';
  end if;

  -- A refunded purchase stays refunded: a later verification, a stale notification or a move to another account never
  -- revives it. Read before the linking rule, which may remove the previous account's rows.
  if exists (select 1 from public.entitlements e where e.purchase_token_hash = p_token_hash and e.status = 'REVOKED') then
    v_status := 'REVOKED';
  end if;

  -- ---------------------------------------------------------------------------------------------- the linking rule
  select * into v_link from public.purchase_links l where l.purchase_token_hash = p_token_hash for update;

  if v_user is null then
    -- A notification about a purchase no account has verified yet: nothing to write. The app verifies it when it opens.
    if not found then
      return jsonb_build_object('result', 'unlinked');
    end if;
    v_user := v_link.user_id;
  else
    if not found then
      -- First verification: the purchase belongs to this account from now on. A concurrent first verification of the
      -- same purchase loses the insert and is decided by the rule below, against the winner's row.
      insert into public.purchase_links (purchase_token_hash, order_id, product_id, user_id, obfuscated_account_id)
      values (p_token_hash, p_order_id, p_product_id, v_user, p_obfuscated_account_id)
      on conflict (purchase_token_hash) do nothing;
      select * into v_link from public.purchase_links l where l.purchase_token_hash = p_token_hash for update;
    end if;

    if v_link.user_id <> v_user then
      -- Another account holds it. It moves only when the purchase was made *for* this account (Play carries the hash the
      -- app sent) and the other link is older than 30 days; a third move needs support.
      if p_obfuscated_account_id is distinct from encode(sha256(convert_to(lower(v_user::text), 'UTF8')), 'hex')
         or v_link.linked_at > now() - interval '30 days' then
        return jsonb_build_object('result', 'linked_elsewhere');
      end if;
      if v_link.relinked_count >= 2 then
        return jsonb_build_object('result', 'review_required');
      end if;
      delete from public.entitlements e where e.user_id = v_link.user_id and e.purchase_token_hash = p_token_hash;
      update public.purchase_links l
        set user_id = v_user, linked_at = now(), relinked_count = l.relinked_count + 1,
            obfuscated_account_id = coalesce(p_obfuscated_account_id, l.obfuscated_account_id),
            order_id = coalesce(p_order_id, l.order_id)
        where l.purchase_token_hash = p_token_hash;
    elsif v_link.order_id is null or v_link.obfuscated_account_id is null then
      update public.purchase_links l
        set order_id = coalesce(l.order_id, p_order_id), obfuscated_account_id = coalesce(l.obfuscated_account_id, p_obfuscated_account_id)
        where l.purchase_token_hash = p_token_hash;
    end if;
  end if;

  -- ---------------------------------------------------------------------------------------------- the rows
  if p_product_id = 'lucento_pro_lifetime' then
    -- Every Pro feature on the phone, forever; and the online services for 365 days from the purchase (D-13).
    v_services_status := case
      when v_status in ('PENDING', 'REVOKED', 'EXPIRED') then v_status
      when v_starts + interval '365 days' > now() then 'ACTIVE'
      else 'EXPIRED'
    end;
    perform public.lucento_write_play_row(v_user, 'PLAY_LIFETIME', v_status, array['LOCAL_PRO'], p_product_id, null, p_token_hash, v_starts, null);
    perform public.lucento_write_play_row(v_user, 'PLAY_LIFETIME_SERVICES', v_services_status, array['CLOUD', 'AI_PRO', 'SHARED'],
      p_product_id, null, p_token_hash, v_starts, v_starts + interval '365 days');
  elsif p_product_id = 'lucento_pro' then
    perform public.lucento_write_play_row(v_user, 'PLAY_SUBSCRIPTION', v_status, array['LOCAL_PRO', 'CLOUD', 'AI_PRO', 'SHARED'],
      p_product_id, p_base_plan_id, p_token_hash, v_starts, p_expires_at);
  else
    perform public.lucento_write_play_row(v_user, 'PLAY_CLOUD_ADDON', v_status, array['CLOUD', 'AI_PRO', 'SHARED'],
      p_product_id, p_base_plan_id, p_token_hash, v_starts, p_expires_at);
  end if;

  return jsonb_build_object('result', 'ok', 'status', v_status);
end;
$$;

-- One row per (account, source, product). A different purchase of the same product (a resubscription) replaces the row,
-- except that a stale purchase's ending never overwrites a newer purchase that is still live.
create or replace function public.lucento_write_play_row(
  p_user uuid, p_source text, p_status text, p_grants text[], p_product_id text, p_base_plan_id text,
  p_token_hash text, p_starts_at timestamptz, p_expires_at timestamptz
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.entitlements as e
    (user_id, source, status, grants, product_id, base_plan_id, purchase_token_hash, starts_at, expires_at, verified_at)
  values
    (p_user, p_source, p_status, p_grants, p_product_id, p_base_plan_id, p_token_hash, p_starts_at, p_expires_at, now())
  on conflict (user_id, source, (coalesce(product_id, ''))) do update
    set status = excluded.status,
        grants = excluded.grants,
        base_plan_id = excluded.base_plan_id,
        purchase_token_hash = excluded.purchase_token_hash,
        starts_at = excluded.starts_at,
        expires_at = excluded.expires_at,
        verified_at = now()
    where e.purchase_token_hash is not distinct from excluded.purchase_token_hash
       or excluded.status in ('ACTIVE', 'TRIAL', 'GRACE', 'CANCELLED_ACTIVE', 'PENDING')
       or e.status not in ('ACTIVE', 'TRIAL', 'GRACE', 'CANCELLED_ACTIVE', 'PENDING', 'ON_HOLD', 'PAUSED')
$$;

-- A refund or chargeback (Play's voided purchases): every row of that purchase ends, on whichever account holds it.
-- Returns how many rows changed, so the daily check can report what it caught.
create or replace function public.revoke_play_purchase(p_token_hash text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'revoke_play_purchase: token hash must be 64 lower-case hex characters' using errcode = '22023';
  end if;
  update public.entitlements e set status = 'REVOKED', verified_at = now()
    where e.purchase_token_hash = p_token_hash and e.status <> 'REVOKED';
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

revoke all on function public.apply_play_purchase(uuid, text, text, text, text, text, text, timestamptz, timestamptz),
  public.lucento_write_play_row(uuid, text, text, text[], text, text, text, timestamptz, timestamptz),
  public.revoke_play_purchase(text)
  from public, anon, authenticated;
grant execute on function public.apply_play_purchase(uuid, text, text, text, text, text, text, timestamptz, timestamptz),
  public.revoke_play_purchase(text)
  to service_role;

commit;

-- ======================================================================================= verify (read-only)
-- Run after the commit. Every row should say ok.
select check_name, case when passed then 'ok' else 'MISSING' end as result from (values
  ('Lucento Shared tables', to_regclass('public.shared_spaces') is not null and to_regclass('public.space_members') is not null and to_regclass('public.space_invites') is not null),
  ('Shared: transactions.created_by', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'transactions' and column_name = 'created_by')),
  ('Multicurrency: ledger_settings', to_regclass('public.ledger_settings') is not null),
  ('Multicurrency: transactions.base_amount_minor', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'transactions' and column_name = 'base_amount_minor')),
  ('Entitlements tables', to_regclass('public.entitlements') is not null and to_regclass('public.purchase_links') is not null and to_regclass('lucento_private.plan_limits') is not null),
  ('consume_ai_request for signed-in only', to_regprocedure('public.consume_ai_request()') is not null and has_function_privilege('authenticated', 'public.consume_ai_request()', 'execute') and not has_function_privilege('anon', 'public.consume_ai_request()', 'execute')),
  ('apply_play_purchase for the service role only', exists (select 1 from pg_proc where proname = 'apply_play_purchase' and has_function_privilege('service_role', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute') and not has_function_privilege('anon', oid, 'execute'))),
  ('delete_my_account (applied earlier)', to_regprocedure('public.delete_my_account()') is not null),
  ('RLS on every new table', not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relkind = 'r' and not c.relrowsecurity and (n.nspname, c.relname) in (('public','shared_spaces'),('public','space_members'),('public','space_invites'),('public','ledger_settings'),('public','entitlements'),('public','purchase_links'),('lucento_private','plan_limits'))))
) as checks(check_name, passed);
